#!/usr/bin/env node
// Generates typed contracts from the product spec (docs/ehr-spec). Run after `npm run api` / `npm run validate` in
// docs/ehr-spec, then commit the output. Never edit generated files by hand.
//
//   packages/shared/src/contracts/api-types.ts   TS types for every components.schemas entry
//   packages/shared/src/contracts/operations.ts  operation registry (method, path, x-roles, x-audit, x-transitions, ...)
//                                                 + OperationTypes map (params/query/body/response per operationId)
//   packages/shared/src/contracts/states.ts      state machines and labels from spec/states.yaml (INV-DATA-03)
//   packages/shared/src/contracts/roles.ts       roles from spec/roles.yaml (can_sign, clinical_read, home)
//   apps/api/src/contracts/schemas.json          JSON Schemas for request validation (x-* keywords stripped)
//
// js-yaml is resolved from the spec's own tooling install (docs/ehr-spec/node_modules) so the app workspaces carry
// no extra dependency. Run `npm install` in docs/ehr-spec first.
import { createRequire } from "node:module";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const specDir = join(root, "docs/ehr-spec");
const yaml = createRequire(join(specDir, "package.json"))("js-yaml");

const openapi = yaml.load(readFileSync(join(specDir, "api/openapi.yaml"), "utf8"));
const states = yaml.load(readFileSync(join(specDir, "spec/states.yaml"), "utf8"));
const roles = yaml.load(readFileSync(join(specDir, "spec/roles.yaml"), "utf8"));
const schemas = openapi.components.schemas;
const header = "// GENERATED by tools/codegen.mjs from docs/ehr-spec. Do not edit by hand.\n";

// ---------------------------------------------------------------- JSON Schema -> TS
const ident = (s) => (/^[A-Za-z_$][\w$]*$/.test(s) ? s : JSON.stringify(s));
const refName = (ref) => ref.replace("#/components/schemas/", "");

function tsType(s, indent = "") {
  if (!s) return "unknown";
  if (s.$ref) return refName(s.$ref);
  if (s.const !== undefined) return JSON.stringify(s.const);
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (s.oneOf) return s.oneOf.map((x) => tsType(x, indent)).join(" | ");
  if (s.anyOf) return s.anyOf.map((x) => tsType(x, indent)).join(" | ");
  if (s.allOf) return s.allOf.map((x) => tsType(x, indent)).join(" & ");
  const types = Array.isArray(s.type) ? s.type : [s.type];
  return types
    .map((t) => {
      switch (t) {
        case "string":
          return s.format === "binary" ? "BinaryData" : "string";
        case "integer":
        case "number":
          return "number";
        case "boolean":
          return "boolean";
        case "null":
          return "null";
        case "array":
          return `Array<${tsType(s.items, indent)}>`;
        case "object":
          return objectType(s, indent);
        default:
          return "unknown";
      }
    })
    .join(" | ");
}

function objectType(s, indent) {
  const props = s.properties ?? {};
  const keys = Object.keys(props);
  if (!keys.length) return s.additionalProperties === false ? "Record<string, never>" : "Record<string, unknown>";
  const req = new Set(s.required ?? []);
  const inner = indent + "  ";
  const lines = keys.map((k) => {
    const p = props[k];
    const doc = p.description ? `${inner}/** ${String(p.description).replace(/\*\//g, "* /").replace(/\n/g, " ")} */\n` : "";
    const ro = p.readOnly ? "readonly " : "";
    return `${doc}${inner}${ro}${ident(k)}${req.has(k) ? "" : "?"}: ${tsType(p, inner)};`;
  });
  return `{\n${lines.join("\n")}\n${indent}}`;
}

let types = header + "/* eslint-disable */\n\n/** File content (multipart upload or binary download). The web client passes a Blob/File. */\nexport type BinaryData = Uint8Array | ArrayBuffer | object;\n\n";
for (const [name, s] of Object.entries(schemas)) {
  if (s.description) types += `/** ${String(s.description).replace(/\*\//g, "* /").replace(/\n/g, " ")} */\n`;
  const t = tsType(s);
  types += t.startsWith("{") ? `export interface ${name} ${t}\n\n` : `export type ${name} = ${t};\n\n`;
}

types += `/** Schema name -> type (used by the API's schema-driven serialiser). */\nexport interface SchemaTypes {\n${Object.keys(schemas).map((n) => `  ${n}: ${n};`).join("\n")}\n}\n`;

// ---------------------------------------------------------------- operations
const paramRefs = openapi.components.parameters;
const resolveParam = (p) => (p.$ref ? paramRefs[p.$ref.split("/").pop()] : p);
const ops = [];
for (const [path, item] of Object.entries(openapi.paths)) {
  if (path.startsWith("/fhir/")) continue; // served by apps/fhir (ADR-011)
  for (const [method, op] of Object.entries(item)) {
    if (!op || typeof op !== "object" || !op.operationId) continue;
    const params = (op.parameters ?? []).map(resolveParam);
    const success = Object.entries(op.responses).find(([c]) => c.startsWith("2"));
    const [status, resp] = success ?? ["200", {}];
    const content = resp.content ?? {};
    const responseType = content["application/json"]
      ? "json"
      : Object.keys(content).length
        ? "binary"
        : "none";
    const security = (op.security ?? openapi.security).flatMap((s) => Object.keys(s));
    const bodyContent = op.requestBody?.content ?? {};
    const bodyMedia = Object.keys(bodyContent)[0];
    ops.push({
      id: op.operationId,
      method: method.toUpperCase(),
      path,
      summary: op.summary ?? "",
      tag: op.tags?.[0] ?? "",
      security,
      roles: op["x-roles"] ?? null,
      audit: op["x-audit"] ?? null,
      transitions: op["x-transitions"] ?? [],
      stepUp: op["x-step-up"] ?? false,
      phi: op["x-phi"] ?? false,
      integration: op["x-integration"] ?? null,
      invariants: op["x-invariants"] ?? [],
      screens: op["x-screens"] ?? [],
      flowSteps: op["x-flow-steps"] ?? [],
      successStatus: Number(status),
      responseType,
      bodyMedia: bodyMedia ?? null,
      bodyRequired: !!op.requestBody?.required,
      pathParams: params.filter((p) => p.in === "path").map((p) => p.name),
      queryParams: params.filter((p) => p.in === "query").map((p) => p.name),
      headerParams: params.filter((p) => p.in === "header").map((p) => p.name),
      _params: params,
      _body: bodyContent[bodyMedia]?.schema,
      _response: content["application/json"]?.schema,
    });
  }
}
ops.sort((a, b) => a.id.localeCompare(b.id));

const meta = ops.map(({ _params, _body, _response, ...m }) => m);
let opsTs = header + "/* eslint-disable */\nimport type * as T from \"./api-types.js\";\n\n";
opsTs += `export interface OperationMeta {
  id: string;
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  summary: string;
  tag: string;
  /** staffAuth | enrollmentToken | portalAuth | webhookSignature | twilioSignature; empty = public */
  security: readonly string[];
  /** x-roles: null = any authenticated principal of the security scheme */
  roles: readonly string[] | null;
  audit: string | null;
  transitions: readonly string[];
  stepUp: boolean | "conditional";
  phi: boolean;
  integration: string | null;
  invariants: readonly string[];
  screens: readonly string[];
  flowSteps: readonly string[];
  successStatus: number;
  responseType: "json" | "binary" | "none";
  bodyMedia: string | null;
  bodyRequired: boolean;
  pathParams: readonly string[];
  queryParams: readonly string[];
  headerParams: readonly string[];
}

export const operations = ${JSON.stringify(Object.fromEntries(meta.map((m) => [m.id, m])), null, 2)} as const satisfies Record<string, OperationMeta>;

export type OperationId = keyof typeof operations;

`;
opsTs += "export interface OperationTypes {\n";
for (const o of ops) {
  const pathT = o._params.filter((p) => p.in === "path");
  const queryT = o._params.filter((p) => p.in === "query");
  const pp = pathT.length ? `{ ${pathT.map((p) => `${ident(p.name)}: string`).join("; ")} }` : "never";
  const qq = queryT.length
    ? `{ ${queryT.map((p) => `${ident(p.name)}${p.required ? "" : "?"}: ${tsType(p.schema).replace(/\b([A-Z]\w+)\b/g, (m) => (schemas[m] ? `T.${m}` : m))}`).join("; ")} }`
    : "never";
  const qualify = (t) => t.replace(/(?<![\w."])([A-Z][A-Za-z0-9]+)(?![\w"])/g, (m) => (schemas[m] ? `T.${m}` : m));
  const body = o._body ? qualify(tsType(o._body, "    ")) : "never";
  const res = o._response ? qualify(tsType(o._response, "    ")) : o.responseType === "binary" ? "T.BinaryData" : "void";
  opsTs += `  ${o.id}: {\n    params: ${pp};\n    query: ${qq};\n    body: ${body};\n    response: ${res};\n  };\n`;
}
opsTs += "}\n";

// ---------------------------------------------------------------- states + roles
const toEnum = (id) => id.toUpperCase().replace(/-/g, "_");
let statesTs = header + `
export interface StateDef { id: string; enumValue: string; label: string }
export interface TransitionDef { from: readonly string[]; to: string; by?: readonly string[]; guard?: string; invariants?: readonly string[] }
export interface MachineDef { id: string; states: readonly StateDef[]; transitions: readonly TransitionDef[] }

`;
const machines = {};
for (const m of states.machines) {
  machines[m.id] = {
    id: m.id,
    states: m.states.map((s) => ({ id: s.id, enumValue: s.id === "new" ? "" : toEnum(s.id), label: s.label })),
    transitions: m.transitions,
  };
}
statesTs += `export const machines = ${JSON.stringify(machines, null, 2)} as const satisfies Record<string, MachineDef>;

export type MachineId = keyof typeof machines;

/** Label for a stored status value (UPPER_SNAKE enum or kebab state id). The only source of status text (INV-DATA-03). */
export function stateLabel(machine: MachineId, value: string | null | undefined): string {
  if (!value) return "—";
  const def = (machines[machine].states as readonly StateDef[]).find((s) => s.enumValue === value || s.id === value);
  return def ? def.label : value;
}

/** Kebab state id for a stored enum value. */
export function stateId(machine: MachineId, enumValue: string): string {
  const def = (machines[machine].states as readonly StateDef[]).find((s) => s.enumValue === enumValue);
  return def ? def.id : enumValue;
}

/** Enum value for a kebab state id. */
export function stateEnum(machine: MachineId, id: string): string {
  const def = (machines[machine].states as readonly StateDef[]).find((s) => s.id === id);
  return def ? def.enumValue : id;
}
`;

let rolesTs = header + `
export interface RoleDef { id: string; name: string; description: string; home: string; can_sign: readonly string[]; clinical_read: string }
export const roles = ${JSON.stringify(Object.fromEntries(roles.roles.map((r) => [r.id, r])), null, 2)} as const satisfies Record<string, RoleDef>;
export type RoleId = keyof typeof roles;
export type StaffRoleId = Exclude<RoleId, "patient" | "system">;
export const staffRoles = ["frontdesk", "ma", "provider", "biller", "manager"] as const satisfies readonly StaffRoleId[];
/** Prisma Role enum value for a spec role id. */
export const roleEnum = (r: StaffRoleId) => r.toUpperCase() as "FRONTDESK" | "MA" | "PROVIDER" | "BILLER" | "MANAGER";
export const roleFromEnum = (r: string) => r.toLowerCase() as StaffRoleId;
`;

// ---------------------------------------------------------------- screen catalog (screens.yaml + spec/ui)
const screensSpec = yaml.load(readFileSync(join(specDir, "spec/screens.yaml"), "utf8")).screens;
const modulesSpec = yaml.load(readFileSync(join(specDir, "spec/modules.yaml"), "utf8")).modules;
const uiScreens = {};
for (const f of ["auth", "home", "schedule", "patients", "chart", "encounter", "inbox", "billing", "reports", "telehealth", "admin", "portal"]) {
  const doc = yaml.load(readFileSync(join(specDir, `spec/ui/${f}.yaml`), "utf8"));
  Object.assign(uiScreens, doc.screens ?? {});
}
const moduleOf = {};
for (const m of modulesSpec) for (const g of m.groups) for (const sid of g.screens) moduleOf[sid] = { module: m.id, nav: m.nav, group: g.name };
const catalog = screensSpec.map((sc) => {
  const ui = uiScreens[sc.id] ?? {};
  return {
    id: sc.id,
    name: sc.name,
    purpose: sc.purpose ?? "",
    roles: sc.roles ?? [],
    route: ui.route ?? null,
    pattern: ui.pattern ?? null,
    up: ui.up ?? null,
    container: ui.container ?? null,
    module: moduleOf[sc.id]?.module ?? null,
    nav: moduleOf[sc.id]?.nav ?? null,
    group: moduleOf[sc.id]?.group ?? null,
  };
});
const screensTs = header + `
export interface ScreenDef {
  id: string;
  name: string;
  purpose: string;
  roles: readonly string[];
  /** Route from spec/ui (null for overlays). */
  route: string | null;
  pattern: string | null;
  up: string | null;
  container: string | null;
  module: string | null;
  nav: string | null;
  group: string | null;
}
export const screens = ${JSON.stringify(Object.fromEntries(catalog.map((c) => [c.id, c])), null, 2)} as const satisfies Record<string, ScreenDef>;
export type ScreenId = keyof typeof screens;
`;

// ---------------------------------------------------------------- JSON Schemas for request validation
function strip(o) {
  if (Array.isArray(o)) return o.map(strip);
  if (o && typeof o === "object") {
    const r = {};
    for (const [k, v] of Object.entries(o)) {
      if (k.startsWith("x-") || k === "example" || k === "examples") continue;
      if (k === "$ref") r[k] = v.replace("#/components/schemas/", "schemas.json#/definitions/");
      else r[k] = k === "properties" ? Object.fromEntries(Object.entries(v).map(([pk, pv]) => [pk, strip(pv)])) : strip(v);
    }
    return r;
  }
  return o;
}
const jsonSchemas = {
  $id: "schemas.json",
  definitions: strip(schemas),
  operations: Object.fromEntries(
    ops.map((o) => [
      o.id,
      {
        params: o._params.some((p) => p.in === "path")
          ? {
              type: "object",
              properties: Object.fromEntries(o._params.filter((p) => p.in === "path").map((p) => [p.name, strip(p.schema)])),
              required: o._params.filter((p) => p.in === "path").map((p) => p.name),
            }
          : null,
        querystring: o._params.some((p) => p.in === "query")
          ? {
              type: "object",
              properties: Object.fromEntries(o._params.filter((p) => p.in === "query").map((p) => [p.name, strip(p.schema)])),
              required: o._params.filter((p) => p.in === "query" && p.required).map((p) => p.name),
            }
          : null,
        body: o.bodyMedia === "application/json" || o.bodyMedia === "application/merge-patch+json" ? strip(o._body) : null,
        response: o._response ? strip(o._response) : null,
      },
    ]),
  ),
};

// ---------------------------------------------------------------- schema doc tags (docs/09-data-model.md)
const prismaSchema = readFileSync(join(root, "prisma/schema.prisma"), "utf8");
const schemaTags = { tenant: [], appendOnly: [], versioned: [], fhir: {}, patientScoped: [], encrypted: {}, phi: {} };
for (const m of prismaSchema.matchAll(/((?:\/\/\/.*\n)*)model (\w+) \{([\s\S]*?)\n\}/g)) {
  const [, tags, name, body] = m;
  if (tags.includes("@tenant")) schemaTags.tenant.push(name);
  if (tags.includes("@append-only")) schemaTags.appendOnly.push(name);
  if (tags.includes("@versioned")) schemaTags.versioned.push(name);
  const fhir = /@fhir (\w+)/.exec(tags);
  if (fhir) schemaTags.fhir[name] = fhir[1];
  if (/\n\s+patientId\s+String/.test(body)) schemaTags.patientScoped.push(name);
  for (const line of body.split("\n")) {
    const f = /^\s+(\w+)\s+\S+.*\/\/\/(.*)$/.exec(line);
    if (!f) continue;
    if (f[2].includes("@encrypted")) (schemaTags.encrypted[name] ??= []).push(f[1]);
    if (f[2].includes("@phi")) (schemaTags.phi[name] ??= []).push(f[1]);
  }
}

const sharedOut = join(root, "packages/shared/src/contracts");
const apiOut = join(root, "apps/api/src/contracts");
mkdirSync(sharedOut, { recursive: true });
mkdirSync(apiOut, { recursive: true });
writeFileSync(join(sharedOut, "api-types.ts"), types);
writeFileSync(join(sharedOut, "operations.ts"), opsTs);
writeFileSync(join(sharedOut, "states.ts"), statesTs);
writeFileSync(join(sharedOut, "roles.ts"), rolesTs);
writeFileSync(join(sharedOut, "screens.ts"), screensTs);
writeFileSync(join(apiOut, "schemas.json"), JSON.stringify(jsonSchemas));
writeFileSync(join(apiOut, "schema-tags.json"), JSON.stringify(schemaTags, null, 2));
console.log(`codegen: ${Object.keys(schemas).length} schemas, ${ops.length} operations, ${states.machines.length} machines`);
